ALTER TABLE unit_types ADD COLUMN pallet_rating_catalog_json LONGTEXT NULL;

-- Layout snapshots created before the rating catalog existed already contain
-- the catalog when they were generated by the v8 backend.  Copy it to the
-- type-level column so Manager and Customer use one rating source after the
-- migration.  Rows without a v8 catalog remain NULL and are reviewed by the
-- normal configuration flow.
UPDATE unit_types
SET pallet_rating_catalog_json = CAST(JSON_EXTRACT(rack_layout_json, '$.result.configuration.palletRatings') AS CHAR)
WHERE rack_layout_json IS NOT NULL
  AND JSON_VALID(rack_layout_json) = 1
  AND JSON_EXTRACT(rack_layout_json, '$.result.configuration.palletRatings') IS NOT NULL;
